import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** The deepest exception in the cause chain. */
    static Throwable rootCause(Throwable t) {
        while (t.getCause() != null) t = t.getCause();
        return t;
    }

    /** Messages from t down to the root. */
    static List<String> messageTrail(Throwable t) {
        var trail = new ArrayList<String>();
        for (Throwable cur = t; cur != null; cur = cur.getCause()) trail.add(cur.getMessage());
        return trail;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("rootCause finds the deepest message", () -> {
            var root = new IllegalArgumentException("root");
