    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("body and cleanup both run when nothing fails", () -> {
            var log = new ArrayList<String>();
            runThenCleanup(() -> log.add("body"), () -> log.add("cleanup"));
            eq(log, List.of("body", "cleanup"));
