        test("a failing body still gets cleaned up", () -> {
            var log = new ArrayList<String>();
            var ex = raises(IllegalStateException.class,
                () -> runThenCleanup(() -> { throw new IllegalStateException("body"); }, () -> log.add("cleanup")), "body");
            eq(ex.getSuppressed().length, 0);
            eq(log, List.of("cleanup"));
