                () -> { throw new IllegalStateException("body"); },
                () -> { throw new IllegalArgumentException("cleanup"); }), "body");
            eq(ex.getSuppressed().length, 1);
            eq(ex.getSuppressed()[0].getClass().getSimpleName(), "IllegalArgumentException");
            eq(ex.getSuppressed()[0].getMessage(), "cleanup");
