                () -> runThenCleanup(() -> { throw new AssertionError("body"); }, () -> log.add("cleanup")), "body");
            eq(log, List.of("cleanup"));
        });
        test("the same exception thrown twice is not suppressed into itself", () -> {
            var shared = new IllegalStateException("shared");
            var ex = raises(IllegalStateException.class,
                () -> runThenCleanup(() -> { throw shared; }, () -> { throw shared; }), "shared");
            eq(ex.getSuppressed().length, 0);
        });
        System.exit(report());
    }
