// ─────────────────────────────────────────────────────────────────────────
//  04 · the cleanup that hid the real error                          ★★★
//  concepts: Throwable.addSuppressed · primary vs cleanup failure · masking by finally
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** Run body then cleanup; if both fail, the body's exception wins and carries the cleanup's as suppressed. */
    static void runThenCleanup(Runnable body, Runnable cleanup) {
        try {
            body.run();
        } catch (Throwable primary) {
            try {
                cleanup.run();
            } catch (Throwable secondary) {
                if (secondary != primary) primary.addSuppressed(secondary);
