import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** Fail fast on null with "name is required"; otherwise the stripped, lower-cased name. */
    static String register(String name) {
        Objects.requireNonNull(name, "name is required");
        return name.strip().toLowerCase(Locale.ROOT);
    }

    /** Logs "reserve <seat>" and marks the seat taken; a seat outside the array is refused before anything happens. */
    static void reserve(boolean[] taken, int seat, List<String> log) {
        Objects.checkIndex(seat, taken.length);
        log.add("reserve " + seat);
        taken[seat] = true;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a null name fails fast with the message", () ->
