// ─────────────────────────────────────────────────────────────────────────
//  09 · the finally that ate the exception                           ★★☆
//  concepts: return in finally · swallowed exceptions · return values captured before finally
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.function.Supplier;

class Exercise {

    /** Holds the LAST id handed out; nextId issues the one after it. */
    static final class Counter {
        int value;

        Counter(int value) {
            this.value = value;
        }
    }

    // TODO: fix — the shipped helpers below. Outages come back as "unknown"
    // instead of failing, and every caller gets the id that was already used.
    /** The body's value, audited; a failure propagates and is audited as "audit:failed". */
    @SuppressWarnings("finally")
    static String fetch(Supplier<String> body, List<String> log) {
        String result = "unknown";
        try {
            result = body.get();
            return result;
        } finally {
            log.add("audit:" + result);
            return result;
        }
    }

    /** Advance the counter and hand out the NEW value. */
    static int nextId(Counter c) {
        try {
            return c.value;
        } finally {
            c.value++;
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a successful fetch returns its value and audits it", () -> {
            var log = new ArrayList<String>();
            eq(fetch(() -> "row-7", log), "row-7");
            eq(log, List.of("audit:row-7"));
        });
        test("a failing fetch propagates its exception", () ->
            raises(IllegalStateException.class,
                () -> fetch(() -> { throw new IllegalStateException("db down"); }, new ArrayList<>()), "db down"));
        test("a failing fetch is still audited", () -> {
            var log = new ArrayList<String>();
            try {
                fetch(() -> { throw new IllegalStateException("db down"); }, log);
            } catch (IllegalStateException expected) {
                // the failure must reach the caller; the audit line must be there anyway
            }
            eq(log, List.of("audit:failed"));
        });
        test("nextId hands out the incremented id", () -> {
            var c = new Counter(41);
            eq(nextId(c), 42);
            eq(c.value, 42);
        });
        test("consecutive ids never repeat (boundary)", () -> {
            var c = new Counter(0);
            eq(List.of(nextId(c), nextId(c)), List.of(1, 2));
            eq(c.value, 2);
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

